args.new_string:
  const leg = document.getElementById("legend");
  leg.innerHTML = monthRows
    .map((r, i) => {
      const v = Number(r.amount) || 0;
      const p = total ? ((v / total) * 100).toFixed(1) : 0;
      const c = Number(r.count) || 0;
      const ms = Array.isArray(r.merchants) ? r.merchants.filter((m) => m && m.name) : [];
      const hasSub = ms.length > 1 || (ms.length === 1 && ms[0].name !== r.category);
      const subHtml = ms
        .slice()
        .sort((a, b) => (Number(b.amount) || 0) - (Number(a.amount) || 0))
        .map(
          (m) =>
            "<li><span>" + esc(m.name) +
            (m.count ? " (" + m.count + "件)" : "") +
            '</span><span class="m-amt">' + yen(Number(m.amount) || 0) + "</span></li>",
        )
        .join("");
      return (
        '<li class="' + (hasSub ? "" : "no-sub") + '">' +
        '<div class="row">' +
        '<span class="caret">▶</span>' +
        '<span class="dot" style="background:' + colorFor(r.category, i) + '"></span>' +
        '<span class="cat">' + esc(r.category) + "</span>" +
        '<span class="amt">' + yen(v) + "</span>" +
        '<span class="pct">' + p + "%</span>" +
        '<span class="cnt">' + (c ? c + "件" : "") + "</span></div>" +
        (hasSub ? '<ul class="mlist">' + subHtml + "</ul>" : "") +
        "</li>"
      );
    })
    .join("");
  leg.onclick = (e) => {
    const li = e.target.closest("li");
    if (li && !li.classList.contains("no-sub")) li.classList.toggle("open");
  };
}
function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"]/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c],
  );
}

