const sum = (arr) => arr.reduce((s, r) => s + (Number(r.monthlyCost) || 0), 0);

const STATUS_COLOR = { "継続": "#334155", "解約予定": "#d97706", "解約済み": "#16a34a" };
let donutChart = null, rankChart = null;

function renderCharts(keep, plan, done, totalSave) {
  // Doughnut: monthly cost split by status
  const dLabels = ["継続（維持）", "解約予定（見込み削減）", "解約済み（達成削減）"];
  const dData = [sum(keep), sum(plan), sum(done)];
  const dColor = ["#334155", "#d97706", "#16a34a"];
  document.getElementById("donutCenter").textContent = yen(sum(plan) + sum(done));
  const dCfg = {
    type: "doughnut",
    data: { labels: dLabels, datasets: [{ data: dData, backgroundColor: dColor, borderColor: "#fff", borderWidth: 2 }] },
    options: {
      responsive: true, maintainAspectRatio: false, cutout: "66%",
      plugins: {
        legend: { position: "bottom", labels: { boxWidth: 10, font: { size: 10 }, padding: 8 } },
        tooltip: { callbacks: { label: (c) => " " + c.label + ": " + yen(c.parsed) + " /月" } },
      },
    },
  };
  if (donutChart) { donutChart.data = dCfg.data; donutChart.update(); } else donutChart = new Chart(document.getElementById("donut"), dCfg);

  // Horizontal bar: services ranked by monthly cost, colored by status
  const ranked = rows.filter((r) => Number(r.monthlyCost) > 0).sort((a, b) => (Number(b.monthlyCost) || 0) - (Number(a.monthlyCost) || 0));
  const rCfg = {
    type: "bar",
    data: {
      labels: ranked.map((r) => r.name),
      datasets: [{
        data: ranked.map((r) => Number(r.monthlyCost) || 0),
        backgroundColor: ranked.map((r) => STATUS_COLOR[r.status] || "#94a3b8"),
        borderRadius: 5,
      }],
    },
    options: {
      indexAxis: "y", responsive: true, maintainAspectRatio: false,
      scales: {
        x: { ticks: { callback: (v) => "¥" + (v / 1000) + "k" }, grid: { color: "#eef2f7" } },
        y: { ticks: { font: { size: 11 } }, grid: { display: false } },
      },
      plugins: {
        legend: { display: false },
        tooltip: { callbacks: { label: (c) => " " + yen(c.parsed.x) + " /月（" + (ranked[c.dataIndex].status) + "）" } },
      },
    },
  };
  if (rankChart) { rankChart.data = rCfg.data; rankChart.update(); } else rankChart = new Chart(document.getElementById("rank"), rCfg);
}

